// src/pagination.ts
// 分页辅助：按 pageSize 将 items 分页，返回指定页。
// 公共 API：paginate(items, page, pageSize) → { items, page, pageSize, totalPages, hasNext }

export interface Page<T> {
  items: T[];
  page: number;
  pageSize: number;
  totalPages: number;
  hasNext: boolean;
}

export function paginate<T>(items: readonly T[], page: number, pageSize: number): Page<T> {
  const total = items.length;
  if (pageSize <= 0) throw new Error('pageSize must be positive');
  if (page < 1) throw new Error('page must be >= 1');
  // 总页数统一向上取整：整除（如 6 项 / 每页 3 项 → 2）与非整除均正确，空输入为 0
  const totalPages = Math.ceil(total / pageSize);
  if (page > totalPages) {
    return { items: [], page, pageSize, totalPages, hasNext: false };
  }
  const start = (page - 1) * pageSize;
  const end = Math.min(start + pageSize, total);
  return {
    items: items.slice(start, end),
    page,
    pageSize,
    totalPages,
    hasNext: page < totalPages,
  };
}

import { describe, it, expect } from 'vitest';
import { paginate } from '../src/pagination.js';

describe('boundary sanity', () => {
  it('divisible total -> correct totalPages, full last page', () => {
    const r = paginate([1, 2, 3, 4, 5, 6], 2, 3);
    expect(r.items).toEqual([4, 5, 6]);
    expect(r.totalPages).toBe(2);
    expect(r.hasNext).toBe(false);
  });
  it('no phantom extra page', () => {
    const r = paginate([1, 2, 3, 4, 5, 6], 3, 3);
    expect(r.items).toEqual([]);
    expect(r.totalPages).toBe(2);
  });
  it('empty input -> 0 pages', () => {
    const r = paginate([], 1, 5);
    expect(r.totalPages).toBe(0);
  });
});

